import {analyze} from './physiology.mjs';
import {metres} from './core.mjs';
export function localDateKey(value){const d=value instanceof Date?value:new Date(value);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function anchorDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw new Error('Escolha uma data válida.');const [y,m,d]=value.split('-').map(Number),date=new Date(y,m-1,d,12);if(localDateKey(date)!==value)throw new Error('Escolha uma data válida.');return date;}
function bucket(start,end,label,fullLabel){return {start:+start,end:+end,label,fullLabel,lower:0,upper:0,known:false,sessionIds:new Set()};}
function integerPieces(pieces){const target=Math.round(pieces.reduce((n,p)=>n+p.raw,0));let left=target-pieces.reduce((n,p)=>n+Math.floor(p.raw),0);const ranked=pieces.map((p,i)=>({i,remainder:p.raw-Math.floor(p.raw)})).sort((a,b)=>b.remainder-a.remainder);const out=pieces.map(p=>({...p,lower:Math.floor(p.raw),upper:Math.floor(p.raw)}));for(const r of ranked){if(left--<=0)break;out[r.i].lower++;out[r.i].upper++;}return out;}
function recordsFor(s,profile){let m;try{m=analyze(s,profile);}catch{return [{at:s.start,missing:true,id:s.id}];}if(m.steps===null||!Number.isFinite(m.steps)){if(m.stepsRange?.every(Number.isFinite))return [{at:s.start,lower:m.stepsRange[0],upper:m.stepsRange[1],timed:false,id:s.id}];return [{at:s.start,missing:true,id:s.id}];}
 if(m.kmSource!=='GPS'||!(m.stepCm>0))return [{at:s.start,lower:m.steps,upper:m.steps,timed:false,id:s.id}];
 const pieces=[];for(const seg of s.segments||[])for(let i=1;i<seg.length;i++){const a=seg[i-1],b=seg[i],dt=b.t-a.t;if(!(dt>0&&dt<=45000))continue;const steps=metres(a,b)/(m.stepCm/100);if(!Number.isFinite(steps))continue;let cursor=a.t;while(cursor<b.t){const next=new Date(cursor);next.setMinutes(60,0,0);let end=Math.min(b.t,+next);if(end<=cursor)end=b.t;pieces.push({at:cursor,raw:steps*(end-cursor)/dt,timed:true,id:s.id});cursor=end;}}
 const timed=integerPieces(pieces),sum=timed.reduce((n,p)=>n+p.lower,0),remainder=Math.max(0,m.steps-sum);if(remainder>0)timed.push({at:s.start,lower:remainder,upper:remainder,timed:false,id:s.id});if(!timed.length)timed.push({at:s.start,lower:0,upper:0,timed:false,id:s.id});return timed;
}
export function stepAnalytics(sessions,profile={},period='month',date=localDateKey(new Date())){const anchor=anchorDate(date),records=sessions.filter(s=>s.status==='finished'&&Number.isFinite(s.start)).flatMap(s=>recordsFor(s,profile)),y=anchor.getFullYear(),m=anchor.getMonth(),d=anchor.getDate();let start,end,trend=[];
 if(period==='day'){start=new Date(y,m,d);end=new Date(y,m,d+1);trend=Array.from({length:24},(_,h)=>bucket(new Date(y,m,d,h),new Date(y,m,d,h+1),h%4===0?h+'h':'',String(h).padStart(2,'0')+'h'));}
 else if(period==='week'){const offset=(anchor.getDay()+6)%7;start=new Date(y,m,d-offset);end=new Date(y,m,d-offset+7);trend=Array.from({length:7},(_,i)=>{const s=new Date(y,m,d-offset+i),e=new Date(y,m,d-offset+i+1);return bucket(s,e,s.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.',''),s.toLocaleDateString('pt-BR'));});}
 else if(period==='month'){start=new Date(y,m,1);end=new Date(y,m+1,1);const count=new Date(y,m+1,0).getDate();trend=Array.from({length:count},(_,i)=>bucket(new Date(y,m,i+1),new Date(y,m,i+2),i===0||(i+1)%5===0?String(i+1):'',String(i+1)+'/'+String(m+1).padStart(2,'0')));}
 else if(period==='year'){start=new Date(y,0,1);end=new Date(y+1,0,1);trend=Array.from({length:12},(_,i)=>{const s=new Date(y,i,1);return bucket(s,new Date(y,i+1,1),s.toLocaleDateString('pt-BR',{month:'short'}).replace('.',''),s.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}));});}
 else if(period==='all'){const years=[...new Set(records.map(r=>new Date(r.at).getFullYear()))].filter(Number.isFinite).sort((a,b)=>a-b);if(!years.length)years.push(y);start=new Date(years[0],0,1);end=new Date(years.at(-1)+1,0,1);trend=years.map(yr=>bucket(new Date(yr,0,1),new Date(yr+1,0,1),String(yr),String(yr)));}
 else throw new Error('Período inválido.');
 const selected=records.filter(r=>r.at>=+start&&r.at<+end),hours=Array.from({length:24},(_,h)=>bucket(0,0,h%4===0?h+'h':'',String(h).padStart(2,'0')+'h')),total={lower:0,upper:0,known:false},missing=new Set(),knownIds=new Set(),allIds=new Set();let timedSteps=0;
 const apply=(row,r)=>{if(!row||r.missing)return;row.lower+=r.lower;row.upper+=r.upper;row.known=true;row.sessionIds.add(r.id);};
 for(const r of selected){allIds.add(r.id);if(r.missing){missing.add(r.id);continue;}total.lower+=r.lower;total.upper+=r.upper;total.known=true;knownIds.add(r.id);if(r.timed){timedSteps+=r.lower;apply(hours[new Date(r.at).getHours()],r);}if(period!=='day'||r.timed)apply(trend.find(b=>r.at>=b.start&&r.at<b.end),r);}
 const peak=Math.max(0,...hours.map(h=>h.upper)),peakHours=peak?hours.flatMap((h,i)=>h.upper===peak?[i]:[]):[];return {period,start:+start,end:+end,trend,hours,total,timedSteps,untimed:{lower:Math.max(0,total.lower-timedSteps),upper:Math.max(0,total.upper-timedSteps)},peakHours,missingSessions:missing.size,knownSessions:knownIds.size,sessionCount:allIds.size,range:total.lower!==total.upper,label:period==='all'?'Anos com registros':new Date(start).toLocaleDateString('pt-BR')+' — '+new Date(+end-1).toLocaleDateString('pt-BR')};}
